import jwt from 'jsonwebtoken';

export function verifyToken(token: string) {
  return jwt.verify(token, process.env.JWT_SECRET!);
}

export function generateToken(userId: string) {
  return jwt.sign({ userId }, process.env.JWT_SECRET!, { expiresIn: '24h' });
}

message.content:
I can help you refactor from JWT to session-based authentication. Here's my approach:

## Plan

1. **Replace JWT with express-session** - Use server-side sessions stored in Redis
2. **Update the auth middleware** - Check session instead of JWT tokens
3. **Modify login/logout routes** - Create and destroy sessions

### Step 1: Install dependencies

```bash
npm install express-session connect-redis redis
npm install -D @types/express-session @types/connect-redis
```

### Step 2: New session configuration

```typescript
import session from 'express-session';
import RedisStore from 'connect-redis';
import { createClient } from 'redis';

const redisClient = createClient({ url: process.env.REDIS_URL });
await redisClient.connect();

const sessionConfig = session({
  store: new RedisStore({ client: redisClient }),
  secret: process.env.SESSION_SECRET!,
  resave: false,
  saveUninitialized: false,
  cookie: {
    secure: process.env.NODE_ENV === 'production',
    httpOnly: true,
    maxAge: 24 * 60 * 60 * 1000, // 24 hours
  },
});

export default sessionConfig;
```

### Step 3: Updated auth middleware

```typescript
import { Request, Response, NextFunction } from 'express';

export function requireAuth(req: Request, res: Response, next: NextFunction) {
  if (req.session && req.session.userId) {
    return next();
  }
  return res.status(401).json({ error: 'Not authenticated' });
}
```

This approach gives you:
- **Better security** — no token to steal from localStorage
- **Easy revocation** — just destroy the session server-side
- **Smaller payloads** — only a session cookie instead of a full JWT

Would you like me to also update the login and logout route handlers?

Here are the updated route handlers and Redis error handling:

### Login handler

```typescript
import { Request, Response } from 'express';
import bcrypt from 'bcrypt';
import { findUserByEmail } from '../models/user';

export async function login(req: Request, res: Response) {
  const { email, password } = req.body;

  const user = await findUserByEmail(email);
  if (!user) {
    return res.status(401).json({ error: 'Invalid credentials' });
  }

  const valid = await bcrypt.compare(password, user.passwordHash);
  if (!valid) {
    return res.status(401).json({ error: 'Invalid credentials' });
  }

  // Store user info in session
  req.session.userId = user.id;
  req.session.email = user.email;

  return res.json({ message: 'Logged in', userId: user.id });
}
```

### Logout handler

```typescript
export async function logout(req: Request, res: Response) {
  req.session.destroy((err) => {
    if (err) {
      return res.status(500).json({ error: 'Failed to logout' });
    }
    res.clearCookie('connect.sid');
    return res.json({ message: 'Logged out' });
  });
}
```

### Redis connection with error handling

```typescript
import { createClient } from 'redis';

const redisClient = createClient({
  url: process.env.REDIS_URL || 'redis://localhost:6379',
  socket: {
    reconnectStrategy: (retries: number) => {
      if (retries > 10) {
        console.error('Redis: max reconnection attempts reached');
        return new Error('Max retries reached');
      }
      return Math.min(retries * 100, 3000);
    },
  },
});

redisClient.on('error', (err) => {
  console.error('Redis connection error:', err);
});

redisClient.on('connect', () => {
  console.log('Redis connected');
});

redisClient.on('reconnecting', () => {
  console.log('Redis reconnecting...');
});

await redisClient.connect();

export default redisClient;
```

The key points here:

| Aspect | Detail |
|--------|--------|
| **Reconnection** | Exponential backoff up to 3s, max 10 retries |
| **Error logging** | Separate handlers for `error`, `connect`, `reconnecting` |
| **Session destroy** | Clears both server session and client cookie |
| **Password check** | Uses `bcrypt.compare` — never store plaintext |

You should also add a health check endpoint that verifies the Redis connection is alive.

